CREATE TABLE "better_supabase"."time_invoice_entries" (
  "entry_id"   uuid                     NOT NULL,
  "tenant_id"  uuid                     NOT NULL,
  "invoice_id" uuid                     NOT NULL,
  "rate"       bigint                   NOT NULL,
  "currency"   character(3)             NOT NULL,
  "seconds"    bigint                   NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "time_invoice_entries_pkey" PRIMARY KEY (entry_id)
);

ALTER TABLE "better_supabase"."time_invoice_entries"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."time_rates" (
  "id"             uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"      uuid                     NOT NULL,
  "user_id"        uuid,
  "subject_type"   text,
  "subject_id"     text,
  "rate"           bigint                   NOT NULL,
  "currency"       character(3)             NOT NULL,
  "effective_from" date                     NOT NULL DEFAULT CURRENT_DATE,
  "created_by"     uuid,
  "created_at"     timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "time_rates_check" CHECK (((subject_type IS NULL) = (subject_id IS NULL))),
  CONSTRAINT "time_rates_currency_check" CHECK ((currency ~ '^[A-Z]{3}$'::text)),
  CONSTRAINT "time_rates_pkey" PRIMARY KEY (id),
  CONSTRAINT "time_rates_rate_check" CHECK ((rate >= 0)),
  CONSTRAINT "time_rates_tenant_id_user_id_subject_type_subject_id_effect_key" UNIQUE NULLS NOT DISTINCT (tenant_id, user_id, subject_type, subject_id, effective_from)
);

ALTER TABLE "better_supabase"."time_rates"
  ENABLE ROW LEVEL SECURITY;

